<?php

declare(strict_types=1);

use App\Controllers\AuthController;
use App\Core\Request;
use App\Core\Response;
use App\Core\Router;
use App\Core\View;

require_once __DIR__ . '/../vendor/autoload.php';

ini_set('display_errors', '0');
error_reporting(E_ALL);
date_default_timezone_set('UTC');

set_error_handler(
    static function (int $severity, string $message, string $file, int $line): never {
        throw new ErrorException($message, 0, $severity, $file, $line);
    }
);

// Rejects session IDs not generated by the server (session fixation protection).
ini_set('session.use_strict_mode', '1');
ini_set('session.use_only_cookies', '1');
session_set_cookie_params([
    'httponly' => true,   // JavaScript cannot read the session cookie.
    'samesite' => 'Lax',  // Extra CSRF protection layer on top of the CSRF token.
    'secure' => false,
]);
session_start();

$request = new Request();
$router = new Router();
$router->add('GET', '/', AuthController::class, 'home', 'guest');
$router->add('GET', '/login', AuthController::class, 'login', 'guest');
$router->add('POST', '/login', AuthController::class, 'login', 'guest');
$router->add('GET', '/register', AuthController::class, 'register', 'guest');
$router->add('POST', '/register', AuthController::class, 'register', 'guest');

try {
    $router->dispatch($request);
} catch (Throwable $exception) {
    error_log((string) $exception);

    if (str_starts_with($request->path(), '/api/')) {
        Response::json(['error' => 'Internal server error'], 500);
    }

    (new View())->render('error', [
        'title' => '500 Error',
        'status' => 500,
        'message' => 'Internal server error',
    ], 500);
}